import React, { useState } from 'react';
import IOSCard from './IOSCard';
import { PatientInfo } from '../types';

interface Props {
  patient: PatientInfo;
}

const RiskStratification: React.FC<Props> = ({ patient }) => {
  const [mrd, setMrd] = useState({ d15: '', d33: '', w12: '' });
  const [selectedGenes, setSelectedGenes] = useState<string[]>([]);
  const [extra, setExtra] = useState<string[]>([]);

  const toggleGene = (gene: string) => {
    setSelectedGenes(prev => prev.includes(gene) ? prev.filter(g => g !== gene) : [...prev, gene]);
  };

  const toggleExtra = (item: string) => {
    setExtra(prev => prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]);
  };

  const getRiskLevel = () => {
    const age = parseFloat(patient.age);
    const wbc = parseFloat(patient.initialWbc);
    const mrd15 = parseFloat(mrd.d15);
    const mrd33 = parseFloat(mrd.d33);
    const mrdW12 = parseFloat(mrd.w12);

    // HR Criteria
    const isHR = 
      mrd15 >= 10 || 
      mrd33 >= 1 || 
      mrdW12 >= 0.01 ||
      selectedGenes.some(g => ['MLL', 'LowHypo', 'iAMP21', 'IKZF1+', 'TCF3-HLF'].includes(g)) ||
      extra.includes('Failure');

    if (isHR) return { level: '高危 (High Risk, HR)', color: 'text-red-600', bg: 'bg-red-50' };

    // IR Criteria
    const isIR = 
      age >= 10 || 
      wbc >= 50 || 
      extra.includes('T-ALL') || 
      extra.includes('CNSL/TL') ||
      selectedGenes.includes('Ph+') || 
      selectedGenes.includes('Ph-like') || 
      selectedGenes.includes('t(1;19)') ||
      (mrd15 >= 0.1 && mrd15 < 10) ||
      (mrd33 >= 0.01 && mrd33 < 1);

    if (isIR) return { level: '中危 (Intermediate Risk, IR)', color: 'text-orange-500', bg: 'bg-orange-50' };

    // LR Criteria
    if (age >= 1 && age < 10 && wbc < 50 && mrd15 < 0.1 && mrd33 < 0.01) {
      return { level: '低危 (Low Risk, LR)', color: 'text-green-600', bg: 'bg-green-50' };
    }

    return { level: '评估中...', color: 'text-gray-400', bg: 'bg-gray-50' };
  };

  const risk = getRiskLevel();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <IOSCard title="危险度结果">
        <div className={`p-4 rounded-xl text-center ${risk.bg}`}>
          <div className={`text-lg font-bold ${risk.color}`}>{risk.level}</div>
        </div>
      </IOSCard>

      <IOSCard title="疗效评估 (MRD %)">
        <div className="space-y-3">
          {['d15', 'd33', 'w12'].map((day) => (
            <div key={day} className="flex justify-between items-center py-1">
              <span className="text-sm font-medium text-gray-700 uppercase">{day}</span>
              <input 
                type="number" 
                placeholder="0.00" 
                value={(mrd as any)[day]}
                onChange={(e) => setMrd(prev => ({ ...prev, [day]: e.target.value }))}
                className="w-20 text-right text-sm border-b border-gray-100 outline-none"
              />
            </div>
          ))}
        </div>
      </IOSCard>

      <IOSCard title="遗传学异常">
        <div className="grid grid-cols-2 gap-2">
          {['Ph+', 'Ph-like', 'MLL', 't(1;19)', 'LowHypo', 'iAMP21', 'IKZF1+', 'TCF3-HLF'].map(gene => (
            <button 
              key={gene}
              onClick={() => toggleGene(gene)}
              className={`text-xs py-2 px-1 rounded-lg border text-center transition-all ${
                selectedGenes.includes(gene) ? 'bg-blue-500 border-blue-500 text-white' : 'border-gray-200 text-gray-500'
              }`}
            >
              {gene}
            </button>
          ))}
        </div>
      </IOSCard>

      <IOSCard title="临床因素">
        <div className="space-y-2">
          {[
            { id: 'T-ALL', label: 'T-ALL' },
            { id: 'CNSL/TL', label: '伴CNSL或睾丸受累(TL)' },
            { id: 'Failure', label: 'd33未达CR/纵隔瘤灶缩小<1/3' }
          ].map(item => (
            <button 
              key={item.id}
              onClick={() => toggleExtra(item.id)}
              className={`w-full text-left text-xs p-3 rounded-xl border flex justify-between items-center ${
                extra.includes(item.id) ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-gray-50 border-gray-100 text-gray-500'
              }`}
            >
              {item.label}
              {extra.includes(item.id) && <div className="w-2 h-2 rounded-full bg-blue-500" />}
            </button>
          ))}
        </div>
      </IOSCard>
    </div>
  );
};

export default RiskStratification;

import React, { useState } from 'react';
import IOSCard from './IOSCard';

const MPALModule: React.FC = () => {
  const [markers, setMarkers] = useState<string[]>([]);

  const toggle = (m: string) => setMarkers(prev => 
    prev.includes(m) ? prev.filter(i => i !== m) : [...prev, m]
  );

  const diagnose = () => {
    const hasMyeloid = markers.includes('MPO') || (markers.includes('NSE') && markers.includes('CD11c'));
    const hasT = markers.includes('cCD3') || markers.includes('sCD3');
    const hasB = (markers.includes('CD19_strong') && (markers.includes('CD79a') || markers.includes('cCD22') || markers.includes('CD10'))) ||
                 (markers.includes('CD19_weak') && [markers.includes('CD79a'), markers.includes('cCD22'), markers.includes('CD10')].filter(Boolean).length >= 2);

    if (hasB && hasMyeloid) return 'MPAL (B/Myeloid)';
    if (hasT && hasMyeloid) return 'MPAL (T/Myeloid)';
    if (hasB && hasT) return 'MPAL (B/T)';
    return '不符合MPAL诊断标准';
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <IOSCard title="诊断结果">
        <div className="p-4 bg-blue-50 rounded-xl text-center font-bold text-blue-700">
          {diagnose()}
        </div>
      </IOSCard>

      <IOSCard title="髓系标记 (Myeloid)">
        <div className="space-y-2">
          <button onClick={() => toggle('MPO')} className={`w-full text-left p-3 rounded-xl border text-xs ${markers.includes('MPO') ? 'bg-blue-500 text-white' : 'bg-gray-50'}`}>MPO 强表达 (>3%)</button>
          <div className="grid grid-cols-2 gap-2">
            {['NSE', 'CD11c', 'CD14', 'CD64'].map(m => (
              <button key={m} onClick={() => toggle(m)} className={`p-2 rounded-lg border text-xs ${markers.includes(m) ? 'bg-blue-500 text-white' : 'bg-gray-50'}`}>{m}</button>
            ))}
          </div>
        </div>
      </IOSCard>

      <IOSCard title="T系标记">
        <div className="grid grid-cols-2 gap-2">
          {['cCD3', 'sCD3'].map(m => (
            <button key={m} onClick={() => toggle(m)} className={`p-2 rounded-lg border text-xs ${markers.includes(m) ? 'bg-blue-500 text-white' : 'bg-gray-50'}`}>{m}</button>
          ))}
        </div>
      </IOSCard>

      <IOSCard title="B系标记">
        <div className="space-y-2">
          <div className="flex gap-2">
            <button onClick={() => toggle('CD19_strong')} className={`flex-1 p-2 rounded-lg border text-xs ${markers.includes('CD19_strong') ? 'bg-blue-500 text-white' : 'bg-gray-50'}`}>CD19 强表达</button>
            <button onClick={() => toggle('CD19_weak')} className={`flex-1 p-2 rounded-lg border text-xs ${markers.includes('CD19_weak') ? 'bg-blue-500 text-white' : 'bg-gray-50'}`}>CD19 弱表达</button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {['CD79a', 'cCD22', 'CD10'].map(m => (
              <button key={m} onClick={() => toggle(m)} className={`p-2 rounded-lg border text-xs ${markers.includes(m) ? 'bg-blue-500 text-white' : 'bg-gray-50'}`}>{m}</button>
            ))}
          </div>
        </div>
      </IOSCard>
    </div>
  );
};

export default MPALModule;

import React, { useState } from 'react';
import IOSCard from './IOSCard';

const CNSLModule: React.FC = () => {
  const [inputs, setInputs] = useState({ wbc: '', rbc: '', cells: false, clinical: false, mri: false, bloodWbc: '', bloodRbc: '' });

  const getStatus = () => {
    const wbc = parseFloat(inputs.wbc);
    const rbc = parseFloat(inputs.rbc);
    const bWbc = parseFloat(inputs.bloodWbc);
    const bRbc = parseFloat(inputs.bloodRbc);

    if (inputs.clinical || inputs.mri) return 'CNS3 (确诊CNSL)';

    // CNS3 Criteria
    if (rbc < 10 && wbc > 5 && inputs.cells) return 'CNS3 (确诊CNSL)';
    if (rbc >= 10 && wbc > 5 && inputs.cells) {
       // Steinherz/Bleyer algorithm
       if (bWbc && bRbc && (wbc / rbc) >= 2 * (bWbc / bRbc)) return 'CNS3 (确诊CNSL)';
    }

    // CNS2 Criteria
    if (wbc <= 5 && inputs.cells) return 'CNS2';
    if (rbc >= 10 && wbc > 5 && inputs.cells) return 'CNS2 (Steinherz算法阴性)';

    return 'CNS1 (正常)';
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <IOSCard title="分级结果">
        <div className="p-4 bg-purple-50 rounded-xl text-center font-bold text-purple-700">
          {getStatus()}
        </div>
      </IOSCard>

      <IOSCard title="脑脊液 (CSF) 数据">
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <span className="text-sm">CSF WBC (个/μl)</span>
            <input type="number" value={inputs.wbc} onChange={e => setInputs(p => ({ ...p, wbc: e.target.value }))} className="w-20 text-right outline-none border-b" />
          </div>
          <div className="flex justify-between items-center border-b pb-2">
            <span className="text-sm">CSF RBC (个/μl)</span>
            <input type="number" value={inputs.rbc} onChange={e => setInputs(p => ({ ...p, rbc: e.target.value }))} className="w-20 text-right outline-none border-b" />
          </div>
          <div className="flex items-center space-x-2 py-1">
             <input type="checkbox" checked={inputs.cells} onChange={e => setInputs(p => ({ ...p, cells: e.target.checked }))} className="w-4 h-4 rounded-full" />
             <span className="text-sm">涂片/流式见白血病细胞</span>
          </div>
        </div>
      </IOSCard>

      <IOSCard title="临床及影像">
        <div className="space-y-2">
          <label className="flex items-center space-x-2 p-2 bg-gray-50 rounded-lg">
            <input type="checkbox" checked={inputs.clinical} onChange={e => setInputs(p => ({ ...p, clinical: e.target.checked }))} />
            <span className="text-xs">颅神经麻痹 (排除其他原因)</span>
          </label>
          <label className="flex items-center space-x-2 p-2 bg-gray-50 rounded-lg">
            <input type="checkbox" checked={inputs.mri} onChange={e => setInputs(p => ({ ...p, mri: e.target.checked }))} />
            <span className="text-xs">MRI显示脑或脑膜病变</span>
          </label>
        </div>
      </IOSCard>

      <div className="px-1 py-4">
        <p className="text-[10px] text-gray-400">注：若腰穿有损伤(RBC≥10)，建议录入外周血WBC和RBC以启用Steinherz计算。</p>
      </div>
    </div>
  );
};

export default CNSLModule;

import React, { useState } from 'react';
import IOSCard from './IOSCard';

interface Props {
  bsa: number;
}

const LASPModule: React.FC<Props> = ({ bsa }) => {
  const [fib, setFib] = useState('');
  const [at3, setAt3] = useState('');

  const getAdvice = () => {
    const f = parseFloat(fib);
    const a = parseFloat(at3);
    const advices = [];

    if (f > 0 && f < 0.3) {
      advices.push('纤维蛋白原极低: 建议补充纤维蛋白原制剂 10-20mg/kg (不主张积极补，除非明显出血)。');
    } else if (f > 0 && f < 0.5) {
      advices.push('纤维蛋白原降低: 密切观察，若<0.5且有出血风险建议预防。');
    }

    if (a > 0 && a < 30) {
      advices.push('AT-III 严重降低 (<30%): 极高血栓风险。建议用利伐沙班或达比加群。');
    } else if (a > 0 && a < 60) {
      advices.push('AT-III 降低 (<60%): 建议普通肝素 100 UI/kg/天 或 低分子肝素预防。');
    }

    return advices;
  };

  const advices = getAdvice();

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <IOSCard title="凝血指标录入">
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <span className="text-sm">纤维蛋白原 (Fib, g/L)</span>
            <input type="number" placeholder="0.0" value={fib} onChange={e => setFib(e.target.value)} className="w-24 text-right outline-none border-b" />
          </div>
          <div className="flex justify-between items-center">
            <span className="text-sm">抗凝血酶-III (AT-III, %)</span>
            <input type="number" placeholder="0" value={at3} onChange={e => setAt3(e.target.value)} className="w-24 text-right outline-none border-b" />
          </div>
        </div>
      </IOSCard>

      {advices.length > 0 && (
        <IOSCard title="处理建议">
          <ul className="space-y-3">
            {advices.map((a, i) => (
              <li key={i} className="text-xs text-blue-800 bg-blue-50 p-3 rounded-xl border border-blue-100 flex items-start space-x-2">
                <span className="mt-1 w-1.5 h-1.5 rounded-full bg-blue-400 flex-shrink-0" />
                <span>{a}</span>
              </li>
            ))}
          </ul>
        </IOSCard>
      )}

      <IOSCard title="监测要点">
        <div className="text-[11px] text-gray-500 leading-relaxed space-y-2">
          <p>• 每次L-ASP输注前(d8, d10)及d12-d28每隔一天评估Fib和AT-III。</p>
          <p>• 警惕静脉窦血栓(CVST)，如出现无法解释的头痛或精神萎靡，应查MRI。</p>
          <p>• Fib &lt; 0.5g/L 时，建议补充纤维蛋白原制剂。</p>
          <p>• 血小板 &lt; 20×10⁹/L 时，必须输注血小板支持。</p>
        </div>
      </IOSCard>
    </div>
  );
};

export default LASPModule;

